 public class Project { public string Id=Guid.NewGuid().ToString("N"); public string Title=""; public int Quantity=1; public string Start=""; public string Deadline=""; public int ReviewDays=0; public bool Archived=false; }
 public class Item { public string Id=""; public string ProjectId=""; public string Title=""; public string Kind="任务"; public int Number; public string Due=""; public string Done=""; public string Origin=""; }
 public class Journal { public string Date=""; public string Text=""; }
 public class Settings { public int[] Weights=new int[]{0,20,20,20,20,20,0}; public string WorkStart="09:00"; public string WorkEnd="18:00"; public string SummaryTime="21:00"; public bool Topmost=true; public int X=-1; public int Y=-1; }
 public class State { public List<Project> Projects=new List<Project>(); public List<Item> Items=new List<Item>(); public List<Journal> Journals=new List<Journal>(); public Settings Settings=new Settings(); public string LastPlan=""; public string LastReminder=""; }
 public static class Engine {
  public static string Key(DateTime d) { return d.ToString("yyyy-MM-dd"); }
  public static DateTime Date(string s) { return DateTime.ParseExact(s,"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture); }
  public static bool AdvanceDay(State s,DateTime now){if(s.LastPlan==Key(now))return false;Plan(s,now.Date);return true;}
  public static int MillisecondsUntilMidnight(DateTime now){return Math.Max(1,(int)Math.Ceiling((now.Date.AddDays(1)-now).TotalMilliseconds));}
  public static void Plan(State s, DateTime today, bool redistribute=false) {
   string now=Key(today);
   foreach(Project p in s.Projects.Where(p=>!p.Archived)) {
    for(int n=1;n<=p.Quantity;n++) { string id=p.Id+":"+n; if(!s.Items.Any(i=>i.Id==id)) s.Items.Add(new Item{Id=id, ProjectId=p.Id, Title=p.Title, Number=n}); }
    var pending=s.Items.Where(i=>i.ProjectId==p.Id&&i.Kind=="任务"&&i.Done==""&&(i.Due==""||(redistribute&&String.CompareOrdinal(i.Due,now)>0))).OrderBy(i=>i.Number).ToList();
    if(pending.Count==0)continue;
    DateTime earliest=s.Items.Any(i=>i.ProjectId==p.Id&&i.Kind=="任务"&&i.Due!="")?today.AddDays(1):today;
    DateTime start=Date(p.Start)>earliest?Date(p.Start):earliest, end=Date(p.Deadline);
    var days=new List<DateTime>(); var weights=new List<int>();
    for(DateTime d=start;d<=end;d=d.AddDays(1)) { int w=s.Settings.Weights[(int)d.DayOfWeek]; if(w>0) {days.Add(d);weights.Add(w);} }
    if(days.Count==0) { foreach(Item i in pending) i.Due=Key(end<today?today:end); continue; }
    int count=pending.Count, sum=weights.Sum(), assigned=0; double accum=0;
    for(int d=0;d<days.Count;d++) { accum+=(double)weights[d]*count/sum; int target=d==days.Count-1?count:(int)Math.Round(accum,MidpointRounding.AwayFromZero); while(assigned<target) pending[assigned++].Due=Key(days[d]); }
   }
   s.LastPlan=now;
  }
  public static List<Item> Today(State s,DateTime day) {string date=Key(day); return s.Items.Where(i=>(i.Done==""&&String.CompareOrdinal(i.Due,date)<=0||i.Done==date)&&!s.Projects.Any(p=>p.Id==i.ProjectId&&p.Archived)).OrderBy(i=>i.Done!="").ThenBy(i=>i.Due).ThenBy(i=>i.Kind).ThenBy(i=>i.ProjectId).ThenBy(i=>i.Number).ToList(); }
  public static void Complete(State s,Item item,DateTime day) {item.Done=Key(day); if(item.Kind!="任务")return; Project p=s.Projects.FirstOrDefault(x=>x.Id==item.ProjectId); if(p!=null&&p.ReviewDays>0&&!s.Items.Any(i=>i.Id==item.Id+":review"))s.Items.Add(new Item{Id=item.Id+":review",ProjectId=p.Id,Title=p.Title,Kind="复习",Number=item.Number,Due=Key(day.AddDays(p.ReviewDays)),Origin="来自 "+Key(day)+" 完成的任务"}); }
  public static bool Undo(State s,Item item) {Item review=s.Items.FirstOrDefault(i=>i.Id==item.Id+":review"); if(review!=null&&review.Done!="")return false; if(review!=null)s.Items.Remove(review);item.Done="";return true;}
 }
 public static class Store {
  public static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DeskTaskAssistant");
  public static string FilePath {get{return Path.Combine(Root,"data.json");}}
  public static JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=50000000};
  public static State Load(){Directory.CreateDirectory(Root);if(!File.Exists(FilePath))return new State();try{return Read(FilePath);}catch(Exception){if(File.Exists(FilePath+".bak")){State backup=Read(FilePath+".bak");MessageBox.Show("主数据文件损坏，已读取上次备份。","数据恢复");return backup;}throw new Exception("数据无法读取。请先保留数据文件并从备份恢复："+FilePath);}}
  public static State Read(string path){State s=Json.Deserialize<State>(File.ReadAllText(path,Encoding.UTF8));if(s==null||s.Projects==null||s.Items==null||s.Journals==null||s.Settings==null||s.Settings.Weights==null||s.Settings.Weights.Length!=7||s.Settings.Weights.Any(w=>w<0||w>100)||s.Settings.Weights.Sum()==0)throw new Exception("备份格式无效");foreach(Project p in s.Projects){Engine.Date(p.Start);Engine.Date(p.Deadline);if(p.Quantity<1||p.Quantity>10000||p.ReviewDays<0||p.ReviewDays>3650)throw new Exception("任务数据无效");}foreach(Item i in s.Items){Engine.Date(i.Due);if(i.Done!="")Engine.Date(i.Done);}return s;}
  [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)] static extern bool MoveFileEx(string source,string destination,int flags); public static void Save(State s){Directory.CreateDirectory(Root);string tmp=FilePath+".tmp";File.WriteAllText(tmp,Json.Serialize(s),Encoding.UTF8);if(File.Exists(FilePath))File.Copy(FilePath,FilePath+".bak",true);if(!MoveFileEx(tmp,FilePath,11))throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());}
 }
