 static class Program {
  public static string StartupPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"DeskTaskAssistant.lnk");}}
  public static void SetStartup(bool enabled){if(!enabled){if(File.Exists(StartupPath))File.Delete(StartupPath);return;}Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);dynamic link=shell.CreateShortcut(StartupPath);link.TargetPath=Application.ExecutablePath;link.WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory;link.Description="桌面任务小助手";link.Save();}
  [STAThread] static void Main(string[] args){if(args.Contains("--self-test")){try{Tests.Run();GroupTests.Run();RolloverTests.Run();ManagerViewTests.Run();File.AppendAllText("test-results.txt", "\r\nPASS: grouping, batch quantity, midnight, carryover and per-project reporting checks.");Environment.ExitCode=0;}catch(Exception ex){File.WriteAllText("test-results.txt",ex.ToString());Environment.ExitCode=1;}return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var mutex=new Mutex(false,"Local\\DeskTaskAssistant")){bool acquired=false;try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired){try{using(var signal=EventWaitHandle.OpenExisting("Local\\DeskTaskAssistantReveal"))signal.Set();}catch(WaitHandleCannotBeOpenedException){MessageBox.Show("小助手正在启动，请稍后再次打开。");}return;}Application.ThreadException+=(s,e)=>MessageBox.Show("操作未完成："+e.Exception.Message+"\n请检查磁盘空间，并导出备份。","桌面任务小助手");Application.Run(new Card(Store.Load()));}catch(Exception ex){MessageBox.Show("无法启动："+ex.Message,"桌面任务小助手");}finally{if(acquired)mutex.ReleaseMutex();}}}
 }
 static class Tests {
  static void Check(bool ok,string name){if(!ok)throw new Exception("FAILED: "+name);}
  public static void Run(){DateTime monday=new DateTime(2026,10,12);var s=new State();var p=new Project{Title="测试",Quantity=10,Start=Engine.Key(monday),Deadline=Engine.Key(monday.AddDays(4)),ReviewDays=7};s.Projects.Add(p);Engine.Plan(s,monday);Check(s.Items.Count==10,"quantity");Check(Engine.Today(s,monday).Count==2,"weekday allocation");Item first=Engine.Today(s,monday)[0];Engine.Complete(s,first,monday);Check(s.Items.Count(i=>i.Kind=="复习"&&i.Due=="2026-10-19")==1,"review date");Engine.Complete(s,first,monday);Check(s.Items.Count(i=>i.Kind=="复习")==1,"idempotent review");Check(Engine.Undo(s,first),"undo");Check(s.Items.Count==10,"undo removes review");Engine.Complete(s,first,monday);Engine.Plan(s,monday.AddDays(1));Check(s.Items.Count(i=>i.Kind=="任务")==10,"no duplicates");Check(Engine.Today(s,monday.AddDays(1)).Count(i=>i.Kind=="任务")==3,"carry incomplete into next day");Check(first.Done=="2026-10-12","preserve completed");Engine.Plan(s,monday.AddDays(8));Check(Engine.Today(s,monday.AddDays(8)).Count(i=>i.Kind=="任务")==9,"all overdue tasks visible");Check(Engine.Today(s,monday.AddDays(8)).Any(i=>i.Kind=="复习"),"overdue review visible");s.Items.Add(new Item{Id="extra",Title="附加",Kind="附加",Due="2026-10-23"});Check(!Engine.Today(s,monday.AddDays(8)).Any(i=>i.Id=="extra"),"future hidden");Check(Engine.Today(s,monday.AddDays(11)).Any(i=>i.Id=="extra"),"future appears");p.Archived=true;Check(!Engine.Today(s,monday.AddDays(8)).Any(i=>i.ProjectId==p.Id),"archived hidden");var weighted=new State();weighted.Settings.Weights=new int[]{0,80,20,0,0,0,0};weighted.Projects.Add(new Project{Title="权重",Quantity=10,Start="2026-10-12",Deadline="2026-10-13"});Engine.Plan(weighted,monday);Check(weighted.Items.Count(i=>i.Due=="2026-10-12")==8,"weighted 80 percent");Check(weighted.Items.Count(i=>i.Due=="2026-10-13")==2,"weighted 20 percent");string json=Store.Json.Serialize(s);Check(Store.Json.Deserialize<State>(json).Items.Count==s.Items.Count,"json round trip");File.WriteAllText("test-results.txt","PASS: 16 scheduling, review, rollover, archive, extra task, and persistence checks.");}
 }
}
